package org.usbworkbench;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class ArchiveTest {
 static int checks;static void yes(boolean b,String m){if(!b)throw new AssertionError(m);checks++;}
 static OpticalImage.Source source(File file)throws IOException{RandomAccessFile f=new RandomAccessFile(file,"r");long size=f.length();return new OpticalImage.Source(){public long size(){return size;}public void read(long at,byte[] b,int off,int n)throws IOException{if(at<0||n>size-at)throw new IOException("BOUNDS");f.seek(at);f.readFully(b,off,n);}public void close()throws IOException{f.close();}};}
 static WimFiles.RandomFile output(File path)throws IOException{File parent=path.getParentFile();parent.mkdirs();if(!path.createNewFile())throw new IOException("EXISTS");RandomAccessFile f=new RandomAccessFile(path,"rw");return new WimFiles.RandomFile(){public long size()throws IOException{return f.length();}public int read(long at,byte[] b)throws IOException{f.seek(at);return f.read(b);}public void write(long at,byte[] b)throws IOException{f.seek(at);f.write(b);}public void truncate(long n)throws IOException{f.setLength(n);}public void sync()throws IOException{f.getFD().sync();}public void close()throws IOException{f.close();}};}
 public static void main(String[] args)throws Exception{File root=new File("artifacts/archive-fixtures"),libs=new File("app/src/main/jniLibs/arm64-v8a");
 for(String name:new String[]{"owned.zip","owned.tar.gz","owned.tar.xz","owned.7z","many.zip","test_read_format_rar5_stored.rar","test_read_format_rar5_compressed.rar"}){File input=new File(root,name);if(!input.exists())continue;File dest=new File(root,name+".output");if(dest.exists())try(java.util.stream.Stream<Path> paths=Files.walk(dest.toPath())){paths.sorted(Comparator.reverseOrder()).forEach(p->{try{Files.delete(p);}catch(IOException e){throw new RuntimeException(e);}});}dest.mkdirs();try(OpticalImage.Source s=source(input)){ArchiveTools.Manifest m=ArchiveTools.scan(libs,s,1048576,(a,b)->{},()->false);yes(!m.entries.isEmpty(),"native listing "+name);yes(ArchiveTools.listing(m).startsWith("ARCHIVE_LIST"),"listing");Map<String,ArchiveTools.Entry> paths=new HashMap<>();for(ArchiveTools.Entry e:m.entries)if(e.directory)new File(dest,e.path).mkdirs();else if(!e.special)paths.put(e.output(),e);Map<String,String> hashes=ArchiveTools.extract(libs,s,m,new WimFiles.Store(){public void capacity(long n){}public WimFiles.RandomFile create(String n)throws IOException{return output(new File(dest,paths.get(n).path));}},(a,b)->{},()->false);yes(hashes.size()==paths.size(),"all outputs");for(Map.Entry<String,ArchiveTools.Entry> e:paths.entrySet())try(InputStream in=new FileInputStream(new File(dest,e.getValue().path))){yes(DiskTools.sha256(in,e.getValue().size,(a,b)->{}).equals(hashes.get(e.getKey())),"full readback "+e.getKey());}System.out.println("PASS actual native archive list/extract/readback "+name);}}
 for(String name:new String[]{"unsafe.zip","duplicate.zip","link.tar"})try(OpticalImage.Source s=source(new File(root,name))){try{ArchiveTools.scan(libs,s,1048576,(a,b)->{},()->false);throw new AssertionError("unsafe accepted "+name);}catch(IOException e){yes(e.getMessage().startsWith("ARCHIVE_"),"unsafe rejection "+name+" "+e);}}
 try(OpticalImage.Source s=source(new File(root,"owned.zip"))){try{ArchiveTools.scan(libs,s,16,(a,b)->{},()->false);throw new AssertionError("limit");}catch(IOException e){yes(e.getMessage().startsWith("ARCHIVE_"),"expansion limit");}try{ArchiveTools.scan(libs,s,1048576,(a,b)->{},()->true);throw new AssertionError("cancel");}catch(IOException e){yes(e.getMessage().equals("CANCELLED"),"cancel");}}
 byte[] original=Files.readAllBytes(new File(root,"owned.zip").toPath());boolean[] changed={false};OpticalImage.Source mutable=new OpticalImage.Source(){public long size(){return original.length;}public void read(long at,byte[] b,int off,int n){System.arraycopy(original,(int)at,b,off,n);if(changed[0]&&at<=10&&10<at+n)b[off+10-(int)at]^=1;}public void close(){}};ArchiveTools.Manifest plan=ArchiveTools.scan(libs,mutable,1048576,(a,b)->{},()->false);changed[0]=true;try{ArchiveTools.extract(libs,mutable,plan,new WimFiles.Store(){public void capacity(long n){}public WimFiles.RandomFile create(String n){return new ArchiveTools.MemoryFile();}},(a,b)->{},()->false);throw new AssertionError("source change accepted");}catch(IOException e){yes(e.getMessage().equals("ARCHIVE_CHANGED"),"valid archive metadata mutation detected "+e);}
 System.out.println("PASS: "+checks+" actual archive/UTF8/CRC/nativeRPC/readback/unsafe/limit/cancel assertions");
 }
}
